import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { FaBars, FaTimes } from "react-icons/fa";
import {
  FiChevronDown,
  FiChevronRight,
  FiGrid,
  FiInbox,
  FiBox,
  FiAlertTriangle,
  FiShoppingBag,
  FiCheckCircle,
  FiMapPin,
  FiTrendingUp,
  FiBell,
  FiUser,
  FiSettings,
  FiActivity,
  FiHome
} from "react-icons/fi";
import { LuLogOut } from "react-icons/lu";
import { getSocket, joinSellerRoom } from "../../../utils/socket";
import { logoutSeller } from "../../../utils/authSession";

const SellerDashboardLayout = ({ children, activeTab }) => {
  const [sidebarActive, setSidebarActive] = useState(false);
  const [openMenus, setOpenMenus] = useState({
    requests: ["incoming-requests", "submitted-proposals", "participated-requests", "not-participated-requests", "rejected-requests"].includes(activeTab),
    products: ["all-products", "add-product"].includes(activeTab),
    inventory: ["inventory-list", "stock-alerts"].includes(activeTab),
    orders: ["active-orders", "completed-orders", "cancelled-orders"].includes(activeTab),
    delivery: ["delivery-zones", "delivery-settings"].includes(activeTab),
  });

  const [hasIncoming, setHasIncoming] = useState(false);
  const [hasActiveOrders, setHasActiveOrders] = useState(false);

  useEffect(() => {
    const checkLiveRequestsAndActiveOrders = async () => {
      const token = localStorage.getItem("sellerToken");
      if (!token) return;

      const baseURL = process.env.REACT_APP_BACKEND_URL || "http://localhost:5001";
      const headers = { "Authorization": `Bearer ${token}` };

      try {
        // 1. Fetch live product requests
        const resProductReq = await fetch(`${baseURL}/api/productRequest/seller/product-requests?requestType=PRODUCT&status=PENDING&limit=1`, { headers });
        const dataProductReq = await resProductReq.json();
        
        // 2. Fetch live prescription requests
        const resPrescriptionReq = await fetch(`${baseURL}/api/productRequest/seller/product-requests?requestType=PRESCRIPTION&status=PENDING&limit=1`, { headers });
        const dataPrescriptionReq = await resPrescriptionReq.json();

        const hasProduct = dataProductReq.success && Array.isArray(dataProductReq.data) && dataProductReq.data.length > 0;
        const hasPrescription = dataPrescriptionReq.success && Array.isArray(dataPrescriptionReq.data) && dataPrescriptionReq.data.length > 0;

        setHasIncoming(hasProduct || hasPrescription);
      } catch (err) {
        console.error("Error fetching live requests for sidebar indicator:", err);
      }

      try {
        // 3. Fetch active product orders
        const resProductOrders = await fetch(`${baseURL}/api/productRequest/seller/orders?orderStatus=active&requestType=PRODUCT&limit=1`, { headers });
        const dataProductOrders = await resProductOrders.json();

        // 4. Fetch active prescription orders
        const resPrescriptionOrders = await fetch(`${baseURL}/api/productRequest/seller/orders?orderStatus=active&requestType=PRESCRIPTION&limit=1`, { headers });
        const dataPrescriptionOrders = await resPrescriptionOrders.json();

        const hasProductOrders = dataProductOrders.success && Array.isArray(dataProductOrders.data) && dataProductOrders.data.length > 0;
        const hasPrescriptionOrders = dataPrescriptionOrders.success && Array.isArray(dataPrescriptionOrders.data) && dataPrescriptionOrders.data.length > 0;

        setHasActiveOrders(hasProductOrders || hasPrescriptionOrders);
      } catch (err) {
        console.error("Error fetching active orders for sidebar indicator:", err);
      }
    };

    checkLiveRequestsAndActiveOrders();

    // Socket.io real-time listener for live sidebar indicators
    const socket = getSocket();
    const sellerId = localStorage.getItem("sellerId");
    if (sellerId) {
      joinSellerRoom(sellerId);
    }

    socket.on("newProductRequest", checkLiveRequestsAndActiveOrders);
    socket.on("requestUpdated", checkLiveRequestsAndActiveOrders);
    socket.on("quotationSubmitted", checkLiveRequestsAndActiveOrders);
    socket.on("newOrder", checkLiveRequestsAndActiveOrders);
    socket.on("orderUpdated", checkLiveRequestsAndActiveOrders);
    socket.on("requestExpired", checkLiveRequestsAndActiveOrders);

    return () => {
      socket.off("newProductRequest", checkLiveRequestsAndActiveOrders);
      socket.off("requestUpdated", checkLiveRequestsAndActiveOrders);
      socket.off("quotationSubmitted", checkLiveRequestsAndActiveOrders);
      socket.off("newOrder", checkLiveRequestsAndActiveOrders);
      socket.off("orderUpdated", checkLiveRequestsAndActiveOrders);
      socket.off("requestExpired", checkLiveRequestsAndActiveOrders);
    };
  }, []);

  const navigate = useNavigate();

  useEffect(() => {
    setOpenMenus((prev) => ({
      ...prev,
      requests: prev.requests || ["incoming-requests", "submitted-proposals", "participated-requests", "not-participated-requests", "rejected-requests"].includes(activeTab),
      products: prev.products || ["all-products", "add-product"].includes(activeTab),
      inventory: prev.inventory || ["inventory-list", "stock-alerts"].includes(activeTab),
      orders: prev.orders || ["active-orders", "completed-orders", "cancelled-orders"].includes(activeTab),
      delivery: prev.delivery || ["delivery-zones", "delivery-settings"].includes(activeTab),
    }));
  }, [activeTab]);

  const toggleSidebar = () => {
    setSidebarActive(!sidebarActive);
  };

  const toggleMenu = (menu) => {
    setOpenMenus((prev) => ({
      ...prev,
      [menu]: !prev[menu],
    }));
  };

  const handleLogout = () => {
    logoutSeller({ reason: "manual", navigate });
  };

  return (
    <>
      {/* Mobile Drawer Overlay */}
      <div className="mobile-menu d-lg-none d-block">
        <button
          type="button"
          className="close-button text-body hover-text-main"
          onClick={toggleSidebar}
        >
          <FaTimes />
        </button>
      </div>

      {/* Mobile Overlay Backdrop — tap to close sidebar */}
      <div
        className={`sidebar-backdrop ${sidebarActive ? 'visible' : ''}`}
        onClick={() => setSidebarActive(false)}
        aria-hidden="true"
      />

      <section className={`dashboard ${sidebarActive ? "active" : ""}`}>
        <div className="dashboard__inner d-flex">

          {/* Dashboard Sidebar */}
          <div className={`dashboard-sidebar ${sidebarActive ? "active" : ""}`}>
            <button
              type="button"
              className="dashboard-sidebar__close d-lg-none d-flex text-body hover-text-main"
              onClick={toggleSidebar}
            >
              <FaTimes style={{ color: "#777", fontSize: "16px" }} />
            </button>

            <div className="dashboard-sidebar__inner">
              <Link to="/shop" className="logo mb-4 d-flex justify-content-center w-100">
                <img
                  src="/assets/images/logo/BHARATLOGO-01.png"
                  alt="Logo"
                  className="white-version"
                  style={{
                    height: "70px",
                    objectFit: "contain",
                  }}
                />
              </Link>
              <Link to="/shop" className="logo favicon mb-48">
                <img
                  src="/assets/images/logo/BHARATLOGO-01.png"
                  alt="Favicon Logo"
                  style={{ height: "65px", width: "65px" }}
                />
              </Link>

              {/* Sidebar Menu Items */}
              <ul className="sidebar-list">

                {/* 1. Dashboard Link */}
                <li className="sidebar-list__item">
                  <Link
                    to="/seller-dashboard"
                    onClick={() => setSidebarActive(false)}
                    className={`sidebar-list__link cursor-pointer ${activeTab === "dashboard" ? "activePage" : ""
                      }`}
                  >
                    <span className="sidebar-list__icon">
                      <FiGrid size={18} />
                    </span>
                    <span className="text">Dashboard</span>
                  </Link>
                </li>

                 <li className="sidebar-list__item">
                  <Link
                    to="/seller-dashboard/profile"
                    onClick={() => setSidebarActive(false)}
                    className={`sidebar-list__link cursor-pointer ${activeTab === "profile" || activeTab === "settings" ? "activePage" : ""
                      }`}
                  >
                    <span className="sidebar-list__icon">
                      <FiUser size={18} />
                    </span>
                    <span className="text">Profile</span>
                  </Link>
                </li>

                {/* 2. Requests Collapsible Menu */}
                <li className="sidebar-list__item">
                  <Link
                    to="/seller-dashboard/incoming-requests"
                    onClick={() => setSidebarActive(false)}
                    className={`sidebar-list__link cursor-pointer ${["incoming-requests", "submitted-proposals", "participated-requests", "not-participated-requests", "rejected-requests"].includes(activeTab) ? "activePage" : ""}`}
                  >
                    <div className="d-flex align-items-center gap-2">
                      <span className="sidebar-list__icon">
                        <FiInbox size={18} />
                      </span>
                      <span className="text">Requests</span>
                      {hasIncoming && (
                        <span 
                          className="rounded-circle bg-danger" 
                          style={{ 
                            width: "8px", 
                            height: "8px", 
                            marginLeft: "6px",
                            display: "inline-block",
                            boxShadow: "0 0 8px rgba(220, 53, 69, 0.6)",
                            backgroundColor: "#DC3545"
                          }}
                        />
                      )}
                    </div>
                  </Link>
                </li>

                {/* 3. Product Management Collapsible Menu */}
                {/* <li className="sidebar-list__item">
                  <div
                    onClick={() => toggleMenu("products")}
                    className="sidebar-list__link cursor-pointer d-flex align-items-center justify-content-between"
                  >
                    <div className="d-flex align-items-center gap-2">
                      <span className="sidebar-list__icon">
                        <FiBox size={18} />
                      </span>
                      <span className="text">Product Catalog</span>
                    </div>
                    <span className="chevron-icon">
                      {openMenus.products ? <FiChevronDown size={14} /> : <FiChevronRight size={14} />}
                    </span>
                  </div>
                  {openMenus.products && (
                    <ul className="sidebar-submenu">
                      <Link
                        to="/seller-dashboard/all-products"
                        onClick={() => setSidebarActive(false)}
                        className={`sidebar-submenu-item d-block text-decoration-none ${activeTab === "all-products" ? "active-sub-page" : ""
                          }`}
                      >
                        All Products
                      </Link>
                      <Link
                        to="/seller-dashboard/add-product"
                        onClick={() => setSidebarActive(false)}
                        className={`sidebar-submenu-item d-block text-decoration-none ${activeTab === "add-product" ? "active-sub-page" : ""
                          }`}
                      >
                        Add/Edit Product
                      </Link>
                    </ul>
                  )}
                </li> */}

                {/* 4. Inventory Collapsible Menu (Hidden) */}
                {/* <li className="sidebar-list__item">
                  <div
                    onClick={() => toggleMenu("inventory")}
                    className="sidebar-list__link cursor-pointer d-flex align-items-center justify-content-between"
                  >
                    <div className="d-flex align-items-center gap-2">
                      <span className="sidebar-list__icon">
                        <FiAlertTriangle size={18} />
                      </span>
                      <span className="text">Inventory</span>
                    </div>
                    <span className="chevron-icon">
                      {openMenus.inventory ? <FiChevronDown size={14} /> : <FiChevronRight size={14} />}
                    </span>
                  </div>
                  {openMenus.inventory && (
                    <ul className="sidebar-submenu">
                      <Link
                        to="/seller-dashboard/inventory-list"
                        onClick={() => setSidebarActive(false)}
                        className={`sidebar-submenu-item d-block text-decoration-none ${activeTab === "inventory-list" ? "active-sub-page" : ""
                          }`}
                      >
                        Inventory List
                      </Link>
                      <Link
                        to="/seller-dashboard/stock-alerts"
                        onClick={() => setSidebarActive(false)}
                        className={`sidebar-submenu-item d-block text-decoration-none ${activeTab === "stock-alerts" ? "active-sub-page" : ""
                          }`}
                      >
                        Stock Alerts
                      </Link>
                    </ul>
                  )}
                </li> */}

                {/* 5. Orders Collapsible Menu */}
                <li className="sidebar-list__item">
                  <Link
                    to="/seller-dashboard/active-orders"
                    onClick={() => setSidebarActive(false)}
                    className={`sidebar-list__link cursor-pointer ${activeTab === "active-orders" ? "activePage" : ""}`}
                  >
                    <div className="d-flex align-items-center gap-2">
                      <span className="sidebar-list__icon">
                        <FiShoppingBag size={18} />
                      </span>
                      <span className="text">Orders</span>
                      {hasActiveOrders && (
                        <span 
                          className="rounded-circle bg-danger" 
                          style={{ 
                            width: "8px", 
                            height: "8px", 
                            marginLeft: "6px",
                            display: "inline-block",
                            boxShadow: "0 0 8px rgba(220, 53, 69, 0.6)",
                            backgroundColor: "#DC3545"
                          }}
                        />
                      )}
                    </div>
                  </Link>
                </li>

                {/* 6. Prescription Management */}
                {/* <li className="sidebar-list__item">
                  <Link
                    to="/seller-dashboard/prescription-requests"
                    onClick={() => setSidebarActive(false)}
                    className={`sidebar-list__link cursor-pointer ${activeTab === "prescription-requests" ? "activePage" : ""
                      }`}
                  >
                    <span className="sidebar-list__icon">
                      <FiCheckCircle size={18} />
                    </span>
                    <span className="text">Prescriptions</span>
                  </Link>
                </li> */}

                {/* 7. Delivery Management Collapsible Menu */}
                {/* <li className="sidebar-list__item">
                  <div
                    onClick={() => toggleMenu("delivery")}
                    className="sidebar-list__link cursor-pointer d-flex align-items-center justify-content-between"
                  >
                    <div className="d-flex align-items-center gap-2">
                      <span className="sidebar-list__icon">
                        <FiMapPin size={18} />
                      </span>
                      <span className="text">Delivery Mgmt</span>
                    </div>
                    <span className="chevron-icon">
                      {openMenus.delivery ? <FiChevronDown size={14} /> : <FiChevronRight size={14} />}
                    </span>
                  </div>
                  {openMenus.delivery && (
                    <ul className="sidebar-submenu">
                      <Link
                        to="/seller-dashboard/delivery-zones"
                        onClick={() => setSidebarActive(false)}
                        className={`sidebar-submenu-item d-block text-decoration-none ${activeTab === "delivery-zones" ? "active-sub-page" : ""
                          }`}
                      >
                        Delivery Zones
                      </Link>
                      <Link
                        to="/seller-dashboard/delivery-settings"
                        onClick={() => setSidebarActive(false)}
                        className={`sidebar-submenu-item d-block text-decoration-none ${activeTab === "delivery-settings" ? "active-sub-page" : ""
                          }`}
                      >
                        Delivery Settings
                      </Link>
                    </ul>
                  )}
                </li> */}

                {/* 8. Reports & Revenue */}
                <li className="sidebar-list__item">
                  <Link
                    to="/seller-dashboard/reports"
                    onClick={() => setSidebarActive(false)}
                    className={`sidebar-list__link cursor-pointer ${activeTab === "reports" ? "activePage" : ""
                      }`}
                  >
                    <span className="sidebar-list__icon">
                      <FiTrendingUp size={18} />
                    </span>
                    <span className="text">Revenue</span>
                  </Link>
                </li>

                {/* 9. Notifications */}
                {/* <li className="sidebar-list__item">
                  <Link
                    to="/seller-dashboard/notifications"
                    onClick={() => setSidebarActive(false)}
                    className={`sidebar-list__link cursor-pointer ${activeTab === "notifications" ? "activePage" : ""
                      }`}
                  >
                    <span className="sidebar-list__icon">
                      <FiBell size={18} />
                    </span>
                    <span className="text">Notifications</span>
                  </Link>
                </li> */}

                {/* 10. Profile & Settings */}
               

                {/* Logout */}
                <li className="sidebar-list__item mt-4">
                  <div
                    onClick={handleLogout}
                    className="sidebar-list__link cursor-pointer"
                  >
                    <span className="sidebar-list__icon">
                      <LuLogOut size={18} />
                    </span>
                    <span className="text">Logout</span>
                  </div>
                </li>

              </ul>
            </div>
          </div>

          {/* Main Dashboard Body */}
          <div className="dashboard-body">

            {/* Top Navbar */}
            <div className="dashboard-nav bg-white flx-between gap-md-3 gap-2">
              <div className="dashboard-nav__left flx-align gap-md-3 gap-2">
                <button
                  onClick={toggleSidebar}
                  type="button"
                  className="icon-btn bar-icon text-heading bg-gray-seven flx-center"
                  aria-label="Toggle sidebar menu"
                >
                  <FaBars />
                </button>
                <button
                  onClick={toggleSidebar}
                  type="button"
                  className="icon-btn arrow-icon text-heading bg-gray-seven flx-center"
                  aria-label="Toggle sidebar collapse"
                >
                  <img src="/assets/images/icons/angle-right.svg" alt="" loading="lazy" />
                </button>
              </div>

              <div className="dashboard-nav__right">
                <div className="header-right flx-align">
                  <div className="header-right__inner gap-sm-3 gap-2 flx-align d-flex">
                    <div className="header-buttons-container d-flex gap-2">
                      <Link
                        to="/shop"
                        className="header-button"
                        style={{
                          backgroundColor: "#A847F0",
                          color: "#ffffff",
                          padding: "8px 16px",
                          borderRadius: "6px",
                          fontWeight: "700",
                          border: "none",
                          cursor: "pointer",
                          textDecoration: "none",
                          fontSize: "13px",
                          display: "inline-flex",
                          alignItems: "center",
                          gap: "6px"
                        }}
                      >
                        <FiHome size={14} /> Back to Shop
                      </Link>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Dashboard Content Inject */}
            <div style={{ minHeight: "calc(100vh - 200px)" }}>
              {children}
            </div>

            {/* Footer */}
            <div className="dashboard-footer bottom-footer-two mt-32 border-0 bg-white">
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: "20px 30px",
                  minHeight: "60px",
                  fontSize: "14px",
                  flexWrap: "wrap",
                }}
                className="footer-container"
              >
                {/* Left */}
               <p style={{ margin: 0, textAlign: "center" }}>
                 © {new Date().getFullYear()}{" "} <span className="footer-4ceps"><a href="https://www.4ceps.com/"  target="_blank" className="footer-4ceps-link">4ceps</a></span>, All rights reserved.
                </p>

                {/* Center */}
                <div className="footer-links">
                  <Link
                    to="/terms-booking"
                    target="_blank"
                    className="footer-link"
                    style={{ fontSize: "14px" }}
                  >
                    Terms of Service
                  </Link>

                  <Link
                    to="/privacy-policy"
                    target="_blank"
                    className="footer-link"
                    style={{ fontSize: "14px" }}
                  >
                    Privacy Policy
                  </Link>
                    <Link
                    to="/payment-policy"
                    target="_blank"
                    className="footer-link"
                    style={{ fontSize: "14px" }}
                  >
                    Payment Policy
                  </Link>
                </div>

                {/* Right */}
                <a
                  href="https://www.metromindz.com/"
                  target="_blank"
                  className="footer-link footer-designed"
                  style={{ fontSize: "14px" }}
                >
                  Designed and Developed by Metromindz
                </a>
              </div>

              <style>
                {`
      .footer-link {
        text-decoration: none;
        color: inherit;
      }

      .footer-link:hover {
        text-decoration: underline;
      }

       .footer-4ceps:hover {
        text-decoration: underline;
      }

 .footer-4ceps-link {
        text-decoration: none;
        color: inherit; /* This removes the blue color */
        cursor: pointer;
        transition: text-decoration 0.3s ease;
      }

      .footer-4ceps-link:hover {
        text-decoration: underline; 
        color: inherit !important;
      }

      /* Center align Designed... on tablets too */
      @media (max-width: 768px) {
        .footer-container {
          justify-content: center;
          gap: 10px;
        }
        .footer-designed {
          text-align: center;
          width: 100%;
        }
      }

      /* Mobile layout: stack vertically */
      @media (max-width: 426px) {
        .footer-container {
          flex-direction: column;
          justify-content: center;
          align-items: center;
          gap: 12px;
          text-align: center;
        }

        .footer-links {
          display: flex;
          flex-direction: column;
          gap: 6px;
          line-height: 1.6;
        }

        .footer-designed {
          margin-top: 4px;
        }
      }

      @media(max-width:1440px){
      .footer-link{
      font-size:14px;
      }
      }
    @media (max-width: 1024px) {
  .footer-link.footer-designed {
    display: block; /* make it take full width */
    text-align: center;
    width: 100%;
    margin-top: 8px;
  }
}

    `}
              </style>
            </div>
          </div>
        </div>
      </section>

      <style>{`
        /* ---- Sidebar width overrides ---- */
        @media (min-width: 992px) {
          .dashboard:not(.active) .dashboard-sidebar {
            width: 230px !important;
          }
          .dashboard:not(.active) .dashboard-body {
            width: calc(100% - 230px) !important;
          }
          .dashboard.active .dashboard-sidebar {
            width: 70px !important;
            padding: 24px 8px !important;
          }
          .dashboard.active .dashboard-sidebar .text,
          .dashboard.active .dashboard-sidebar .logo {
            display: none !important;
          }
          .dashboard.active .dashboard-sidebar .sidebar-list__icon {
            margin: 0 auto !important;
          }
          .dashboard.active .dashboard-body {
            width: calc(100% - 70px) !important;
          }
          .bar-icon { display: flex !important; }
          .arrow-icon { display: none !important; }
        }

        /* ---- Mobile / Tablet sidebar overlay ---- */
        @media (max-width: 991px) {
          .dashboard-sidebar {
            position: fixed !important;
            left: 0;
            top: 0;
            z-index: 9999;
            height: 100vh !important;
            width: 245px !important;
            transform: translateX(-100%);
            transition: transform 0.3s ease !important;
            box-shadow: 4px 0 24px rgba(0,0,0,0.12);
            overflow-y: auto;
          }
          .dashboard-sidebar.active {
            transform: translateX(0) !important;
          }
          .dashboard-body {
            width: 100% !important;
          }
          /* Hamburger always visible on mobile */
          .bar-icon { display: flex !important; }
          .arrow-icon { display: none !important; }
        }

        /* ---- Mobile overlay backdrop ---- */
        .sidebar-backdrop {
          display: none;
          position: fixed;
          inset: 0;
          background: rgba(0,0,0,0.45);
          z-index: 9998;
        }
        @media (max-width: 991px) {
          .sidebar-backdrop.visible {
            display: block;
          }
        }

        /* ---- Dashboard nav responsive ---- */
        .dashboard-nav {
          position: sticky;
          top: 0;
          z-index: 100;
          padding: 12px 20px !important;
        }
        @media (max-width: 575px) {
          .dashboard-nav {
            padding: 10px 14px !important;
            flex-wrap: wrap;
            gap: 8px !important;
          }
          .header-button {
            font-size: 11px !important;
            padding: 6px 10px !important;
          }
        }

        /* ---- Dashboard body content padding ---- */
        .dashboard-body > div:last-of-type {
          padding: 20px;
        }
        @media (max-width: 767px) {
          .dashboard-body > div:last-of-type {
            padding: 12px;
          }
        }

        /* ---- Stat / metric cards grid ---- */
        .seller-stat-grid {
          display: grid;
          grid-template-columns: repeat(4, 1fr);
          gap: 16px;
        }
        @media (max-width: 1199px) {
          .seller-stat-grid {
            grid-template-columns: repeat(2, 1fr);
          }
        }
        @media (max-width: 575px) {
          .seller-stat-grid {
            grid-template-columns: 1fr 1fr;
            gap: 10px;
          }
        }

        /* ---- Tables scrollable on small screens ---- */
        .seller-table-wrap {
          width: 100%;
          overflow-x: auto;
          -webkit-overflow-scrolling: touch;
          border-radius: 12px;
        }
        .seller-table-wrap table {
          min-width: 560px;
        }

        /* ---- Page headings shrink ---- */
        @media (max-width: 575px) {
          .seller-page-title {
            font-size: 18px !important;
          }
          .seller-section-title {
            font-size: 15px !important;
          }
        }

        /* ---- Submenu ---- */
        .sidebar-submenu {
          list-style: none;
          padding-left: 36px;
          margin-top: 5px;
          margin-bottom: 5px;
        }
        .sidebar-submenu-item {
          font-size: 13px;
          color: #64748B;
          padding: 6px 12px;
          cursor: pointer;
          border-radius: 4px;
          transition: all 0.2s ease;
          font-weight: 600;
        }
        .sidebar-submenu-item:hover {
          color: #A847F0;
          background-color: #F9F5FF;
        }
        .active-sub-page {
          color: #A847F0 !important;
          background-color: #F9F5FF !important;
          font-weight: 700;
        }
        .sidebar-list__link {
          user-select: none;
        }
        .activePage > .sidebar-list__link,
        .sidebar-list__item > .activePage {
          color: #A847F0 !important;
          background-color: #F5F3FF !important;
          font-weight: 700 !important;
          border-radius: 8px;
        }
        .chevron-icon {
          display: flex;
          align-items: center;
          color: #94A3B8;
        }
        .sidebar-list__link:hover .chevron-icon {
          color: #A847F0;
        }

        /* ---- Footer responsive ---- */
        @media (max-width: 767px) {
          .footer-container {
            flex-direction: column !important;
            gap: 12px !important;
            text-align: center !important;
            padding: 16px !important;
          }
          .footer-links {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 8px;
          }
        }
        /* ---- Dashboard form input styles: smaller radius, height, and red focus ---- */
        .dashboard-body input,
        .dashboard-body select,
        .dashboard-body textarea,
        .dashboard-body .form-control,
        .dashboard-body .form-select {
          border-radius: 4px !important;
          height: 36px !important;
          padding-top: 4px !important;
          padding-bottom: 4px !important;
          font-size: 13px !important;
        }
        .dashboard-body textarea,
        .dashboard-body textarea.form-control {
          height: auto !important;
          min-height: 80px !important;
        }
        /* ---- Blue focus ring when typing in any input ---- */
        .dashboard-body input:focus,
        .dashboard-body select:focus,
        .dashboard-body textarea:focus,
        .dashboard-body .form-control:focus,
        .dashboard-body .form-select:focus {
          border-color: #2563EB !important;
          box-shadow: 0 0 0 0.18rem rgba(37, 99, 235, 0.2) !important;
          outline: none !important;
        }
        /* ---- Red border only for required fields that are empty/invalid ---- */
        .dashboard-body input:required:not(:focus):invalid,
        .dashboard-body select:required:not(:focus):invalid,
        .dashboard-body textarea:required:not(:focus):invalid,
        .dashboard-body .form-control:required:not(:focus):invalid,
        .dashboard-body .form-select:required:not(:focus):invalid {
          border-color: #ff0000 !important;
          box-shadow: none !important;
        }
        /* ---- While focused on a required+invalid field, keep red ring ---- */
        .dashboard-body input:required:focus:invalid,
        .dashboard-body select:required:focus:invalid,
        .dashboard-body textarea:required:focus:invalid,
        .dashboard-body .form-control:required:focus:invalid,
        .dashboard-body .form-select:required:focus:invalid {
          border-color: #ff0000 !important;
          box-shadow: 0 0 0 0.18rem rgba(255, 0, 0, 0.2) !important;
          outline: none !important;
        }
      `}</style>
    </>
  );
};

export default SellerDashboardLayout;
